examples.template:
MonarchLink(
    text = {{label}},
    onClick = {
        draft = allowed && !locked
        open = true
    },
    variant = MonarchLinkVariant.Inline,
)
if (open) {
    MonarchBottomSheet(
        onDismissRequest = { open = false },
        title = {{label}},
        description = "We share some personal information with advertising partners. You can stop it.",
    ) {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
            MonarchSwitchRow(
                checked = draft && !locked,
                onCheckedChange = { draft = it },
                label = "Allow sale or sharing",
                enabled = !locked,
                description = if (locked) "Your Global Privacy Control signal turned this off." else null,
            )
            MonarchLink(
                text = "Privacy policy",
                onClick = { uriHandler.openUri("https://example.com/privacy") },
                external = true,
            )
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Ghost)
                MonarchButton(
                    text = "Save",
                    onClick = {
                        allowed = draft && !locked
                        open = false
                    },
                    variant = MonarchButtonVariant.Primary,
                )
            }
        }
    }
}

examples.setupTemplate:
var allowed by rememberSaveable { mutableStateOf(true) }
var draft by rememberSaveable { mutableStateOf(true) }
var open by rememberSaveable { mutableStateOf(false) }
// True when the app knows of an opt-out signal for the account, such as Global Privacy Control.
val locked by remember { mutableStateOf(false) }
val uriHandler = LocalUriHandler.current

